function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 200) return 's needs 2 to 200 letters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > Math.floor(s.length / 2)) return 'k is an integer from 1 to s.length / 2.';
  return null;
}

