function minimumChanges(s, k) {
  const n = s.length;
  const cost = Array.from({ length: n }, () => new Array(n + 1).fill(Infinity));
  for (let start = 0; start < n; start++) {
    for (let end = start + 2; end <= n; end++) {
      const len = end - start;
      for (let d = 1; d < len; d++) {
        if (len % d !== 0) {
          continue;
        }
        let changes = 0;
        for (let r = 0; r < d; r++) {
          let left = start + r;
          let right = end - d + r;
          while (left < right) {
            if (s[left] !== s[right]) {
              changes++;
            }
            left += d;
            right -= d;
          }
        }
        cost[start][end] = Math.min(cost[start][end], changes);
      }
    }
  }
  const dp = Array.from({ length: k + 1 }, () => new Array(n + 1).fill(Infinity));
  dp[0][0] = 0;
  for (let parts = 1; parts <= k; parts++) {
    for (let end = 2 * parts; end <= n; end++) {
      for (let start = 2 * (parts - 1); start <= end - 2; start++) {
        dp[parts][end] = Math.min(dp[parts][end], dp[parts - 1][start] + cost[start][end]);
      }
    }
  }
  return dp[k][n];
}

