function minimumChanges(s, k) {
  const pieceCost = (t) => {
    let best = Infinity;
    for (let d = 1; d < t.length; d++) {
      if (t.length % d) continue;
      let total = 0;
      for (let r = 0; r < d; r++) {
        const group = [];
        for (let p = r; p < t.length; p += d) group.push(t[p]);
        const reversed = [...group].reverse();
        let diff = 0;
        for (let q = 0; q < group.length; q++) if (group[q] !== reversed[q]) diff++;
        total += diff / 2;
      }
      best = Math.min(best, total);
    }
    return best;
  };
  const split = (from, left) => {
    if (left === 0) return from === s.length ? 0 : Infinity;
    let best = Infinity;
    for (let to = from + 1; to <= s.length; to++) {
      best = Math.min(best, pieceCost(s.slice(from, to)) + split(to, left - 1));
    }
    return best;
  };
  return split(0, k);
}

