function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(190, 200) : pick(2, 10);
  const alphabet = rand() < 0.4 ? pick(1, 2) : pick(3, 26);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + pick(0, alphabet - 1));
  const k = pick(1, Math.floor(n / 2));
  return [s, k];
}
